"use client";
// @zeus-internal
import { ArrowRight } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useState } from "react";
import { ArtemisButton } from "../../../foundations/button";
import { artemisButtonClasses } from "../../../foundations/button-classes";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { artemisCx } from "../../../lib/utils";
import { SCENARIOS, type Scenario } from "./04-scenario-rail/data";
import { TextReveal } from "./04-scenario-rail/text-reveal";
const VIEWPORT = { once: true, margin: "-50px" } as const;
const PRESS = { scale: 0.99 } as const;
function ScenarioCard({ scenario, active, reduce, onSelect, }: {
    scenario: Scenario;
    active: boolean;
    reduce: boolean;
    onSelect: () => void;
}) {
    const Icon = scenario.icon;
    return (<motion.article layout={!reduce} transition={ARTEMIS_SPRING_LAYOUT} className={artemisCx("art:relative art:min-h-[15rem] art:min-w-0 art:overflow-hidden art:rounded-3xl art:border art:border-border/70 art:bg-background", active ? "art:@min-[1024px]/artemis:flex-[1.7]" : "art:@min-[1024px]/artemis:flex-[0.65]")}>
      <ArtemisButton variant="link" size="none" aria-expanded={active} onClick={onSelect} whileTap={reduce ? undefined : PRESS} className="art:inline-block art:h-auto art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:absolute art:inset-0 art:z-20 art:cursor-pointer art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-inset">
        <span className="art:sr-only">Show {scenario.moment}</span>
      </ArtemisButton>
      <div className="art:absolute art:inset-0 art:overflow-hidden">
        <div aria-hidden="true" className="art:absolute art:-top-20 art:-right-20 art:size-64 art:rounded-full art:bg-primary/8 art:blur-2xl"/>
        <div aria-hidden="true" className="art:absolute art:right-10 art:bottom-10 art:size-28 art:rounded-full art:border art:border-border/70"/>
        <div aria-hidden="true" className="art:absolute art:right-16 art:bottom-16 art:size-16 art:rounded-full art:bg-background/80"/>
      </div>
      <div className="art:relative art:z-10 art:flex art:h-full art:min-h-[15rem] art:flex-col art:p-6 art:@min-[640px]/artemis:p-7 art:@min-[1024px]/artemis:min-h-0 art:@min-[1024px]/artemis:p-8">
        <div className="art:flex art:items-center art:justify-between art:gap-4">
          <span className="art:font-medium art:text-muted-foreground art:text-xs">{scenario.moment}</span>
          <span className="art:grid art:size-10 art:shrink-0 art:place-items-center art:rounded-full art:bg-background art:text-foreground">
            <Icon className="art:size-4.5" strokeWidth={1.7} aria-hidden="true"/>
          </span>
        </div>
        <AnimatePresence initial={false} mode={reduce ? "sync" : "popLayout"}>
          {active ? (<motion.div key="story" className="art:mt-auto art:max-w-xl art:pt-16" initial={reduce ? false : { opacity: 0, filter: "blur(6px)", y: 10 }} animate={{ opacity: 1, filter: "blur(0px)", y: 0 }} exit={reduce ? undefined : { opacity: 0, filter: "blur(6px)", y: 8 }} transition={{ duration: 0.35, ease: ARTEMIS_EASE_OUT }}>
              <h3 className="art:text-balance art:leading-[1.02] art:tracking-[-0.045em] art:text-xl art:font-medium">{scenario.title}</h3>
              <p className="art:mt-4 art:max-w-lg art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:@min-[640px]/artemis:text-base art:@min-[640px]/artemis:leading-7">
                {scenario.body}
              </p>
              <p className="art:mt-7 art:font-medium art:text-sm">{scenario.outcome}</p>
            </motion.div>) : (<motion.h3 key="title" className="art:mt-auto art:max-w-[12rem] art:text-balance art:font-medium art:text-xl art:leading-[1.05] art:tracking-[-0.035em]" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={reduce ? undefined : { opacity: 0 }} transition={reduce ? { duration: 0 } : { duration: 0.2, ease: "easeOut" }}>
              {scenario.title}
            </motion.h3>)}
        </AnimatePresence>
      </div>
    </motion.article>);
}
export default function UseCasesScenarioRail() {
    const reduce = useReducedMotion();
    const [activeId, setActiveId] = useState(SCENARIOS[0].id);
    return (<section className="art:w-full art:overflow-hidden art:bg-background art:px-4 art:py-20 art:text-foreground art:@min-[640px]/artemis:px-6 art:@min-[640px]/artemis:py-24 art:@min-[1024px]/artemis:px-8 art:@min-[1024px]/artemis:py-28">
      <div className="art:mx-auto art:w-full art:max-w-7xl">
        <div className="art:grid art:items-end art:gap-8 art:@min-[1024px]/artemis:grid-cols-[1.1fr_0.9fr] art:@min-[1024px]/artemis:gap-16">
          <div>
            <motion.span className="art:inline-flex art:rounded-full art:border art:border-border/70 art:bg-background art:px-3 art:py-1.5 art:font-medium art:text-muted-foreground art:text-xs" initial={reduce ? false : { opacity: 0, filter: "blur(5px)", y: 8 }} whileInView={{ opacity: 1, filter: "blur(0px)", y: 0 }} viewport={VIEWPORT} transition={{ duration: 0.45, ease: ARTEMIS_EASE_OUT }}>
              Use cases
            </motion.span>
            <TextReveal as="h2" text={["There when the day", "asks more from your team."]} className="art:mt-7 art:max-w-3xl art:text-balance art:tracking-[-0.05em] art:text-4xl art:font-medium"/>
          </div>
          <motion.div className="art:max-w-xl art:@min-[1024px]/artemis:justify-self-end" initial={reduce ? false : { opacity: 0, filter: "blur(6px)", y: 10 }} whileInView={{ opacity: 1, filter: "blur(0px)", y: 0 }} viewport={VIEWPORT} transition={{ duration: 0.5, delay: 0.25, ease: ARTEMIS_EASE_OUT }}>
            <p className="art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:@min-[640px]/artemis:text-base art:@min-[640px]/artemis:leading-7">
              The best tools disappear into the moments people already have. Choose a familiar part of the day to see
              how the experience changes.
            </p>

            <motion.a href="#" tabIndex={0} className={artemisButtonClasses({ variant: "secondary", className: "art:mt-6 art:w-fit art:h-9" })} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : PRESS} transition={ARTEMIS_SPRING_PRESS}>
              See every use case
              <ArrowRight className="art:size-4"/>
            </motion.a>
          </motion.div>
        </div>
        <div className="art:mt-14 art:flex art:flex-col art:gap-3 art:@min-[640px]/artemis:mt-16 art:@min-[1024px]/artemis:h-[31rem] art:@min-[1024px]/artemis:flex-row">
          {SCENARIOS.map((scenario) => (<ScenarioCard key={scenario.id} scenario={scenario} active={scenario.id === activeId} reduce={reduce === true} onSelect={() => setActiveId(scenario.id)}/>))}
        </div>
      </div>
    </section>);
}

